def bounds(text,name):
    m=re.search(rf'(?:(?:async\s+)?function\s+{re.escape(name)}\s*\()',text)
    if not m: raise SystemExit('function missing: '+name)
    i=m.start(); p=text.find('(',m.start()); depth=0; quote=None; esc=False; j=p
    while j<len(text):
        c=text[j]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in "'\"`": quote=c
            elif c=='(': depth+=1
            elif c==')':
                depth-=1
                if depth==0:
                    j+=1; break
        j+=1
    while j<len(text) and text[j].isspace(): j+=1
    if j>=len(text) or text[j]!='{': raise SystemExit('function body missing: '+name)
    depth=1; j+=1; quote=None; esc=False
    while j<len(text) and depth:
        c=text[j]
        if quote:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==quote: quote=None
        else:
            if c in "'\"`": quote=c
            elif c=='{': depth+=1
            elif c=='}': depth-=1
        j+=1
    if depth: raise SystemExit('unbalanced '+name)
    return i,j


def replace_fn(name,new):
    global s
    i,j=bounds(s,name)
    s=s[:i]+new+s[j:]


def replace_once(old,new,label):
    global s
    if old not in s: raise SystemExit('missing marker: '+label)
    s=s.replace(old,new,1)

