omni=r'''
function parseOmniQuery(q){let parts=String(q||'').trim().match(/-?(?:"[^"]+"|'[^']+'|[^,\s]+)/g)||[],positive=[],negative=[];for(let raw of parts){let neg=raw.startsWith('-')&&raw.length>1;if(neg)raw=raw.slice(1);raw=raw.replace(/^['"]|['"]$/g,'').trim().toLowerCase();if(raw)(neg?negative:positive).push(raw)}return{positive,negative,active:positive.length+negative.length>0}}
function omniDateText(...vals){let out=[];for(let v of vals){if(v==null||v==='')continue;let d=new Date(v);if(Number.isNaN(d.getTime()))continue;let pad=n=>String(n).padStart(2,'0'),y=d.getFullYear(),m=d.getMonth()+1,day=d.getDate(),h=d.getHours(),min=d.getMinutes(),h12=h%12||12,ampm=h<12?'am':'pm';out.push(String(v),d.toISOString(),d.toLocaleString(),d.toLocaleDateString(),d.toLocaleTimeString(),`${y}-${pad(m)}-${pad(day)}`,`${m}/${day}/${y}`,`${pad(h)}:${pad(min)}`,`${h12}:${pad(min)} ${ampm}`,d.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric'}),d.toLocaleString('en-US',{month:'long',day:'numeric',year:'numeric'}),d.toLocaleString('en-US',{weekday:'long'}));let now=new Date(),same=x=>x.getFullYear()===y&&x.getMonth()+1===m&&x.getDate()===day;if(same(now))out.push('today');let yd=new Date(now);yd.setDate(now.getDate()-1);if(same(yd))out.push('yesterday')}return out.join(' ')}
function omniMatchesText(text,query){let q=parseOmniQuery(query);if(!q.active)return false;text=String(text||'').toLowerCase();for(let t of q.negative)if(wildcardMatch(text,t))return false;for(let t of q.positive)if(!wildcardMatch(text,t))return false;return true}
function omniSessionText(row,p){let k=row?.key||'',known=state.projectState?.known?.[k]||{},missing=state.projectState?.missing?.[k]||{},recovered=state.projectState?.recovered?.[k]||{};return[p?.name||'Unassigned',row?.label,row?.title,k,row?.preview,row?.agentId,row?.sessionId,known?.label,missing?.label,recovered?.label,omniDateText(row?.updatedAt,known?.lastSeen,missing?.missingSince,missing?.lastSeen,recovered?.recoveredAt)].join(' ')}
function omniProjectText(p){let times=[];for(let k of p.sessions||[]){let row=state.sessions.find(x=>x.key===k),known=state.projectState?.known?.[k];times.push(row?.updatedAt,known?.lastSeen)}return[p.name,p.id,omniDateText(...times)].join(' ')}
function omniRecords(mode,query){let q=parseOmniQuery(query);if(!q.active)return[];let out=[],trash=trashKeySet();if(mode==='global'){let ups={id:UNASSIGNED_ID,name:'Unassigned',sessions:unassignedSessionKeys()};for(let p of [ups,...projects()])if(omniMatchesText(omniProjectText(p),query))out.push({kind:'project',projectId:p.id,label:p.name,meta:`${p.sessions.filter(k=>state.sessions.some(s=>s.key===k)).length} live session(s)`})}let scopeProjects=mode==='active'?[activeProject()]:[{id:UNASSIGNED_ID,name:'Unassigned',sessions:unassignedSessionKeys()},...projects()];let seen=new Set();for(let p of scopeProjects){for(let k of p.sessions||[]){if(seen.has(k)||trash.has(k))continue;seen.add(k);let row=state.sessions.find(x=>x.key===k);if(!row)continue;if(!omniMatchesText(omniSessionText(row,p),query))continue;let stamp=omniDateText(row.updatedAt).split(' ').slice(0,1).join(' ');out.push({kind:'session',projectId:p.id,key:k,label:name(row),meta:`${p.name} · ${fmtTime(row.updatedAt)||stamp||k}`,keyMeta:k})}}return out.slice(0,80)}
function renderOmniResults(mode){let input=$(mode==='global'?'globalOmni':'activeOmni'),drop=$(mode==='global'?'globalOmniResults':'activeOmniResults');if(!input||!drop)return;let q=input.value.trim(),rows=omniRecords(mode,q);if(!q){drop.classList.remove('open');drop.innerHTML='';return}drop.innerHTML=rows.length?rows.map((r,i)=>`<button class="omniHit ${i===0?'selected':''}" data-omni-kind="${r.kind}" data-omni-project="${esc(r.projectId)}"${r.key?` data-omni-key="${esc(r.key)}"`:''}><b><span class="omniKind">${r.kind}</span>${esc(r.label)}</b><small>${esc(r.meta)}${r.keyMeta?' · '+esc(r.keyMeta):''}</small></button>`).join(''):'<div class="omniEmpty">No matches. Search label, project, key, preview, agent/session ID, date or time.</div>';drop.classList.add('open');drop.querySelectorAll('.omniHit').forEach(b=>b.onclick=e=>{e.preventDefault();let kind=b.dataset.omniKind,pid=b.dataset.omniProject,key=b.dataset.omniKey;drop.classList.remove('open');if(kind==='project'){switchProject(pid);return}if(key){state.projectState.activeProjectId=pid;saveProjectState();renderSessions();renderProjectTabs();header();select(key)}})}
function refreshOmniSearches(){renderOmniResults('global');renderOmniResults('active')}
function bindOmniSearches(){for(let mode of ['global','active']){let input=$(mode==='global'?'globalOmni':'activeOmni'),drop=$(mode==='global'?'globalOmniResults':'activeOmniResults');if(!input||input.dataset.bound==='1')continue;input.dataset.bound='1';input.oninput=()=>renderOmniResults(mode);input.onkeydown=e=>{if(e.key==='Escape'){input.value='';drop.classList.remove('open');drop.innerHTML='';return}if(e.key==='Enter'){let first=drop.querySelector('.omniHit');if(first){e.preventDefault();first.click()}}}}document.addEventListener('pointerdown',e=>{if(!e.target.closest?.('.omniWrap'))document.querySelectorAll('.omniDrop.open').forEach(x=>x.classList.remove('open'))})}
let projectTouchGesture=null,projectTouchLastId='',projectTouchLastAt=0;
function bindProjectTouchDnD(){let root=$('sessionList');if(!root||root.dataset.projectTouchBound==='1')return;root.dataset.projectTouchBound='1';let clear=()=>root.querySelectorAll('.projectRow').forEach(n=>n.classList.remove('projectTouchDragging','projectTouchTarget','projectOrderBefore','projectOrderAfter'));root.addEventListener('pointerdown',e=>{if(!['touch','pen'].includes(e.pointerType)||e.button!==0||e.target.closest?.('[data-project-delete]'))return;let row=e.target.closest?.('.projectRow[data-project]');if(!row||row.dataset.project===UNASSIGNED_ID)return;let g={id:row.dataset.project,row,pointerId:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,active:false,timer:null};g.timer=setTimeout(()=>{if(projectTouchGesture===g){g.active=true;window.__projectTouchSuppress=Date.now()+900;row.classList.add('projectTouchDragging');if(navigator.vibrate)try{navigator.vibrate(10)}catch{}}},350);projectTouchGesture=g},{passive:true});root.addEventListener('pointermove',e=>{let g=projectTouchGesture;if(!g||g.pointerId!==e.pointerId)return;g.x=e.clientX;g.y=e.clientY;let dist=Math.hypot(e.clientX-g.startX,e.clientY-g.startY);if(!g.active&&dist>12){clearTimeout(g.timer);projectTouchGesture=null;return}if(!g.active)return;e.preventDefault();clear();g.row.classList.add('projectTouchDragging');let t=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('.projectRow[data-project]');if(t&&t.dataset.project!==UNASSIGNED_ID&&t.dataset.project!==g.id){let r=t.getBoundingClientRect(),after=e.clientY>=r.top+r.height/2;t.classList.add('projectTouchTarget',after?'projectOrderAfter':'projectOrderBefore');t.dataset.projectDropAfter=after?'1':'0'}},{passive:false});root.addEventListener('pointerup',e=>{let g=projectTouchGesture;if(!g||g.pointerId!==e.pointerId)return;if(g.timer)clearTimeout(g.timer);if(g.active){e.preventDefault();let t=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('.projectRow[data-project]');if(t&&t.dataset.project!==UNASSIGNED_ID&&t.dataset.project!==g.id)reorderProjectCard(g.id,t.dataset.project,t.dataset.projectDropAfter==='1');window.__projectTouchSuppress=Date.now()+900}else{let now=Date.now();if(projectTouchLastId===g.id&&now-projectTouchLastAt<=350){window.__projectTouchSuppress=now+800;e.preventDefault();openProjectContext(g.id,g.row);projectTouchLastId='';projectTouchLastAt=0}else{projectTouchLastId=g.id;projectTouchLastAt=now}}projectTouchGesture=null;clear()},{passive:false});root.addEventListener('pointercancel',e=>{if(projectTouchGesture&&projectTouchGesture.pointerId===e.pointerId){clearTimeout(projectTouchGesture.timer);projectTouchGesture=null;clear()}},{passive:true})}
'''
replace_once('function renderProjectSidebar(){',omni+'function renderProjectSidebar(){','omnisearch helpers')

# Keep active-project omnisearch aligned after a project switch.
replace_fn('switchProject',r'''function switchProject(id){if(id!==UNASSIGNED_ID&&!projects().some(p=>p.id===id))return;state.projectState.activeProjectId=id;saveProjectState();let p=activeProject(),k=(p.activeSession&&p.sessions.includes(p.activeSession)?p.activeSession:p.sessions.find(x=>state.sessions.some(s=>s.key===x)))||'';renderSessions();renderProjectTabs();header();refreshOmniSearches();k?select(k):clearSelection()}''')

# Bind new search and touch project-card DnD without disturbing the existing input/session bindings.
i,j=bounds(s,'bind')
old=s[i:j]
old=old.replace("function bind(){", "function bind(){bindOmniSearches();bindProjectTouchDnD();",1)
s=s[:i]+old+s[j:]

# Footer/runtime version marker from the separate touch-IIFE.
s=s.replace("document.querySelectorAll('.version').forEach(n=>n.textContent='v2.9.15');","document.querySelectorAll('.version').forEach(n=>n.textContent='v2.9.16');",1)

# Ensure required new identifiers exist and old redundant dot markup is gone.
checks=['BUILD_VERSION=\'2.9.16\'','id="globalOmni"','id="activeOmni"','function openProjectContext','function reorderProjectCard','function bindProjectTouchDnD',"e.type==='projects.order'","e.type==='project.style'"]
for marker in checks:
    if marker not in s: raise SystemExit('validation marker missing: '+marker)
if '<span id="dot"></span>' in s: raise SystemExit('redundant left connection dot still present')

APP.write_text(s,encoding='utf-8')
